import{_ as l,l as i,o as e,c as n,v as t,p,x as r,d as s,i as P,S as E}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"EVPN","description":"","frontmatter":{"title":"EVPN","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/evpn.md","filePath":"cs/evpn.md","lastUpdated":1789023840000}'),d={name:"cs/evpn.md"};function c(h,a,A,N,V,B){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="evpn" tabindex="-1">EVPN <a class="header-anchor" href="#evpn" aria-label="Permalink to &quot;EVPN&quot;">​</a></h1><div class="epigraph"><p>用 BGP 分发 MAC/IP 与 VNI，替代覆盖网上的洪泛学习；同一套控制面还能做 IRB 与多归。</p><footer>—— 据 RFC 7432 BGP MPLS-Based Ethernet VPN；RFC 8365 EVPN overlay 整理</footer></div><p><a href="/cs/vxlan-overlay">上一课</a> 数据面仍可能洪泛。<a href="/cs/ibgp-route-reflector">iBGP 与 RR</a> 已能传前缀。缺口是 <strong>EVPN 路由类型</strong>：Type 2 MAC/IP、Type 3 组播隧道、Type 1 多归以太网段。本课不把 GRE 头写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>VXLAN 无控制面像透明桥：未知就复制。EVPN：VTEP 把学到的 MAC 打成 BGP NLRI，RR 反射，对端装表——二层学习从数据面迁到控制面，像「MAC 的 BGP」。多归：主机双连两台叶子，以太网段 ESI 防环（DF 选举），对照 RSTP 但在覆盖上。IRB：同一 EVPN 里做 L2 与 L3 网关，减少绕核心。</p><p>不要把 EVPN 写成替代全球 BGP 互联网：这是数据中心/VPN 地址族。</p><p><span class="marginnote">RFC 7432 先对 MPLS，RFC 8365 对 VXLAN。Type 5 前缀路由做 L3VPN 风格。本课不把每类 NLRI 字段背完。</span></p><h3 id="mac-走-bgp" tabindex="-1">MAC 走 BGP <a class="header-anchor" href="#mac-走-bgp" aria-label="Permalink to &quot;MAC 走 BGP&quot;">​</a></h3><p>控制面分发替代洪泛学习。ESI/DF 处理多归。这是 VPN/DC 地址族，不是互联网 eBGP 替代。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：本地学习 → Type 2 通告 → 远端表。对照 MAC 老化：BGP 撤回替代未知洪泛。与 RPKI 无关（不同 AF）。</p>',11)),(e(),p(E,null,{default:r(()=>[P(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEARN%5B%22%E6%9C%AC%E5%9C%B0%20MAC%22%5D%20--%3E%20T2%5B%22EVPN%20Type2%22%5D%0A%20%20T2%20--%3E%20RR%5B%22BGP%20RR%22%5D%0A%20%20RR%20--%3E%20REM%5B%22%E8%BF%9C%E7%AB%AF%20VTEP%20%E8%A1%A8%22%5D%0A%20%20ESI%5B%22ESI%20%E5%A4%9A%E5%BD%92%22%5D%20--%3E%20DF%5B%22%E6%8C%87%E5%AE%9A%E8%BD%AC%E5%8F%91%E8%80%85%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>收敛：MAC 移动要序列号，防双活脑裂。这比 STP TCN 更像 BGP 前缀移动。底层仍 ECMP；EVPN 别把同一流钉死到死掉的 VTEP。IXP 一般不用 EVPN 给公网对等。</p><p>BUM：Type 3 建 ingress-replication 或组播组，收口上一课的洪泛。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 EVPN E-Tree 的全部。GRE 与隧道是下一课。后课默认：覆盖的 MAC 用 BGP 分发；数据面可以是 VXLAN 或 MPLS。</p><p>控制面规模仍受 RR 与表项容量约束，不是无限租户。</p><p>上一课留下的缺口在本课收口；「EVPN」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/gre-tunnels">GRE 与隧道</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EVPN 用 BGP 传 MAC/IP，收敛洪泛。</li><li>ESI/DF 处理多归，替代大 STP 域。</li><li>与 VXLAN 数据面搭配最常见。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 7432；RFC 8365。</li></ul>',10))])}const _=l(d,[["render",c]]);export{T as __pageData,_ as default};
